// SPDX-License-Identifier: CC0-1.0
// Original Source: https://zenn.dev/reputeless/books/standard-cpp-for-competitive-programming/viewer/lis
// ドキュメント: https://github.com/reinsirk/sirkit-cpp-library/blob/main/Document/lis.md

// API一覧
// [長さ・接頭辞]
// 比較はoperator<の狭義弱順序。浮動NaNは検査時に拒否、±infは許可。
// LIS/Length/EndingLengthsはTのコピー構築・代入、Sequenceはコピー構築が必要。
// LIS<Strict>(v): 各接頭辞のLIS長を返す。trueは狭義、falseは広義。空入力は空。
// LISLength<Strict=true>(v): LIS長だけを返す。入力は変更せず、比較はoperator<を使う。
// 時間O(N log(L+1))、追加領域はLISがO(N+L)、LISLengthがO(L)。整列済みの増加列はO(N)。
//
// [復元]
// LISIndicesは汎用型をコピーせず比較し、コピー不能・非default構築の型も扱う。
// 組込み数値型では、末尾値を内部へ複製する場合がある。
// LISIndices<Strict=true>(v): LISを1つ復元し、元配列の添字を昇順で返す。同長の解の選択は任意。
// LISSequence<Strict=true>(v): LISを1つ値の列としてコピーする。空なら空。いずれもO(N log(L+1))時間・O(N)追加領域。
//
// [各末尾の長さ]
// LISEndingLengths<Strict=true>(v): 各要素を末尾とする最長長。狭義/広義、空なら空、O(N log(L+1))時間・O(N+L)領域。
// https://miscalc.hatenablog.com/entry/2024/07/25/212618

#include <algorithm>
#include <array>
#include <utility>
#include <type_traits>
#include <stdexcept>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <limits>
#include <memory>
#include <vector>

// 試作: 1=標準C++の四分探索、2=AVX2 gather、3=AVX2 scalar loads。
#ifndef SIRKIT_LIS_SEARCH_VARIANT
#define SIRKIT_LIS_SEARCH_VARIANT 2
#endif
#if !defined(SIRKIT_DISABLE_SIMD) && (defined(__x86_64__) || defined(__i386__)) && (defined(__GNUC__) || defined(__clang__))
#include <immintrin.h>
#endif


#ifndef SKIP_RUNTIME_CHECKS
#ifndef SIRKIT_LIS_INPUT_CHECK_DEFINED
#define SIRKIT_LIS_INPUT_CHECK_DEFINED
namespace reinsirk::detail {
template <class T>
void check_lis_value(const T& value) {
    if constexpr (std::is_floating_point_v<T>)
        if (std::isnan(value)) throw std::invalid_argument("LIS: NaN input");
}
} // namespace reinsirk::detail
#endif
#endif

#ifndef SIRKIT_LIS_LENGTHS_DEFINED
#define SIRKIT_LIS_LENGTHS_DEFINED
namespace reinsirk::detail {
template <bool Strict, bool Prefix, class T>
auto LISLengths(const std::vector<T>& v) {
    std::vector<T> tails;
    tails.reserve(std::min(v.size(), std::size_t{64}));
    std::vector<std::size_t> lengths;
    if constexpr (Prefix) lengths.resize(v.size());
    std::size_t i = 0;
    for (const auto& value : v) {
#ifndef SKIP_RUNTIME_CHECKS
        reinsirk::detail::check_lis_value(value);
#endif
        const bool extend = tails.empty() || (Strict ? tails.back() < value : !(value < tails.back()));
        if (extend) tails.push_back(value);
        else {
            if constexpr (Strict) *std::lower_bound(tails.begin(), tails.end(), value) = value;
            else *std::upper_bound(tails.begin(), tails.end(), value) = value;
        }
        if constexpr (Prefix) lengths[i++] = tails.size();
    }
    if constexpr (Prefix) return lengths;
    else return tails.size();
}
} // namespace reinsirk::detail
template <bool Strict, class T>
std::vector<std::size_t> LIS(const std::vector<T>& v) {
    return reinsirk::detail::LISLengths<Strict, true>(v);
}
template <bool Strict = true, class T>
std::size_t LISLength(const std::vector<T>& v) {
    return reinsirk::detail::LISLengths<Strict, false>(v);
}
#endif

#ifndef SIRKIT_LIS_RESTORE_DEFINED
#define SIRKIT_LIS_RESTORE_DEFINED
namespace reinsirk::detail {
template <bool Strict, class Index, class T>
std::vector<std::size_t> LISIndicesImpl(const std::vector<T>& v) {
    if (v.empty()) return {};
    std::vector<Index> tails;
    auto previous = std::make_unique_for_overwrite<Index[]>(v.size());
    tails.reserve(std::min(v.size(), std::size_t{64}));
#ifndef SKIP_RUNTIME_CHECKS
    reinsirk::detail::check_lis_value(v[0]);
#endif
    tails.push_back(0);
    for (std::size_t i = 1; i < v.size(); ++i) {
#ifndef SKIP_RUNTIME_CHECKS
        reinsirk::detail::check_lis_value(v[i]);
#endif
        if (Strict ? v[tails.back()] < v[i] : !(v[i] < v[tails.back()])) {
            previous[i] = tails.back();
            tails.push_back(static_cast<Index>(i));
            continue;
        }
        if (Strict ? !(v[tails.front()] < v[i]) : v[i] < v[tails.front()]) {
            tails.front() = static_cast<Index>(i);
            continue;
        }
        std::size_t lo = 1, count = tails.size() - 2;
        while (count != 0) {
            const auto half = count / 2;
            const auto mid = lo + half;
            const bool before = Strict ? v[tails[mid]] < v[i] : !(v[i] < v[tails[mid]]);
            lo = before ? mid + 1 : lo;
            count = before ? count - half - 1 : half;
        }
        previous[i] = tails[lo - 1];
        tails[lo] = static_cast<Index>(i);
    }
    std::vector<std::size_t> result(tails.size());
    auto at = tails.back();
    for (auto i = result.size(); i > 1; --i) {
        result[i - 1] = at;
        at = previous[at];
    }
    result[0] = at;
    return result;
}
template <bool Strict, class Index, bool Repeated = false, class T>
std::vector<std::size_t> LISIndicesWithValues(const std::vector<T>& v) {
    if (v.empty()) return {};
    std::vector<Index> tails;
    std::vector<T> values;
    auto previous = std::make_unique_for_overwrite<Index[]>(v.size());
    tails.reserve(std::min(v.size(), std::size_t{64}));
#ifndef SKIP_RUNTIME_CHECKS
    reinsirk::detail::check_lis_value(v[0]);
#endif
    tails.push_back(0);
    values.reserve(std::min(v.size(), std::size_t{64}));
    values.push_back(v[0]);
    std::size_t i = 1, extensions = 0;
    for (; i < v.size(); ++i) {
#ifndef SKIP_RUNTIME_CHECKS
        reinsirk::detail::check_lis_value(v[i]);
#endif
        if (Strict ? values.back() < v[i] : !(v[i] < values.back())) {
            previous[i] = tails.back();
            if (values.size() == values.capacity()) {
                const auto capacity = values.capacity();
                values.reserve(capacity + std::min(capacity, v.size() - capacity));
            }
            if (values.size() == values.capacity()) std::unreachable();
            values.push_back(v[i]);
            tails.push_back(static_cast<Index>(i));
            if constexpr (Repeated) {
                if (++extensions >= 256 && tails.size() >= 4096) { ++i; break; }
            } else {
                if (tails.size() >= 4096 && tails.size() > (i + 1) / 4) { ++i; break; }
            }
            continue;
        }
        if constexpr (Repeated) extensions = 0;
        if (Strict ? !(values.front() < v[i]) : v[i] < values.front()) {
            tails.front() = static_cast<Index>(i);
            values.front() = v[i];
            continue;
        }
        std::size_t lo = 1, count = tails.size() - 2;
        while (count != 0) {
            const auto half = count / 2;
            const auto mid = lo + half;
            const bool before = Strict ? values[mid] < v[i] : !(v[i] < values[mid]);
            lo = before ? mid + 1 : lo;
            count = before ? count - half - 1 : half;
        }
        previous[i] = tails[lo - 1];
        tails[lo] = static_cast<Index>(i);
        values[lo] = v[i];
    }
    std::vector<T>().swap(values);
    for (; i < v.size(); ++i) {
#ifndef SKIP_RUNTIME_CHECKS
        reinsirk::detail::check_lis_value(v[i]);
#endif
        if (Strict ? v[tails.back()] < v[i] : !(v[i] < v[tails.back()])) {
            previous[i] = tails.back();
            tails.push_back(static_cast<Index>(i));
            continue;
        }
        if (Strict ? !(v[tails.front()] < v[i]) : v[i] < v[tails.front()]) {
            tails.front() = static_cast<Index>(i);
            continue;
        }
        std::size_t lo = 1, count = tails.size() - 2;
        while (count != 0) {
            const auto half = count / 2;
            const auto mid = lo + half;
            const bool before = Strict ? v[tails[mid]] < v[i] : !(v[i] < v[tails[mid]]);
            lo = before ? mid + 1 : lo;
            count = before ? count - half - 1 : half;
        }
        previous[i] = tails[lo - 1];
        tails[lo] = static_cast<Index>(i);
    }
    std::vector<std::size_t> result(tails.size());
    auto at = tails.back();
    for (auto i = result.size(); i > 1; --i) {
        result[i - 1] = at;
        at = previous[at];
    }
    result[0] = at;
    return result;
}

#if !defined(SIRKIT_DISABLE_SIMD) && (defined(__x86_64__) || defined(__i386__)) && (defined(__GNUC__) || defined(__clang__))
#ifndef SIRKIT_LIS_NARROW_SEARCH_DEFINED
#define SIRKIT_LIS_NARROW_SEARCH_DEFINED
#if SIRKIT_LIS_SEARCH_VARIANT == 1
#define SIRKIT_LIS_NARROW_TARGET
#else
#define SIRKIT_LIS_NARROW_TARGET __attribute__((target("avx2")))
#endif
// 両端の比較を済ませた末尾配列を四分し、最後は同じ二分探索で確定する。
template<bool Strict, class Cached, class T>
SIRKIT_LIS_NARROW_TARGET inline std::size_t LISNarrowSearch(const Cached* values, std::size_t size, const T value) {
    std::size_t lo = 1, count = size - 2;
    while (count >= 32) {
        const auto quarter = count / 4;
        const auto p0 = lo + quarter;
        const auto p1 = p0 + quarter;
        const auto p2 = p1 + quarter;
        unsigned segment;
#if SIRKIT_LIS_SEARCH_VARIANT == 1
        const bool b0 = Strict ? values[p0] < value : !(value < values[p0]);
        const bool b1 = Strict ? values[p1] < value : !(value < values[p1]);
        const bool b2 = Strict ? values[p2] < value : !(value < values[p2]);
        segment = static_cast<unsigned>(b0) + static_cast<unsigned>(b1) + static_cast<unsigned>(b2);
#else
        unsigned mask;
        if constexpr (std::is_same_v<T, std::int64_t>) {
#if SIRKIT_LIS_SEARCH_VARIANT == 2
            const auto positions = _mm256_set_epi64x(0, static_cast<std::int64_t>(p2), static_cast<std::int64_t>(p1), static_cast<std::int64_t>(p0));
            const auto samples = _mm256_i64gather_epi64(values, positions, sizeof(T));
#else
            const auto samples = _mm256_set_epi64x(0, values[p2], values[p1], values[p0]);
#endif
            const auto key = _mm256_set1_epi64x(value);
            const auto comparison = Strict ? _mm256_cmpgt_epi64(key, samples) : _mm256_xor_si256(_mm256_cmpgt_epi64(samples, key), _mm256_set1_epi64x(-1));
            mask = static_cast<unsigned>(_mm256_movemask_pd(_mm256_castsi256_pd(comparison))) & 7u;
        } else {
#if SIRKIT_LIS_SEARCH_VARIANT == 2
            // この経路の添字幅はuint32_t以下。キャッシュ長はINT32_MAXまでに制限する。
            const auto positions = _mm_set_epi32(0, static_cast<int>(p2), static_cast<int>(p1), static_cast<int>(p0));
            const auto samples = _mm_i32gather_epi32(values, positions, sizeof(T));
#else
            const auto samples = _mm_set_epi32(0, values[p2], values[p1], values[p0]);
#endif
            const auto key = _mm_set1_epi32(value);
            const auto comparison = Strict ? _mm_cmpgt_epi32(key, samples) : _mm_xor_si128(_mm_cmpgt_epi32(samples, key), _mm_set1_epi32(-1));
            mask = static_cast<unsigned>(_mm_movemask_ps(_mm_castsi128_ps(comparison))) & 7u;
        }
        // 比較結果は0,1,3,7のいずれか。対応する区間番号を取り出す。
        segment = (0x30002010u >> (mask * 4)) & 3u;
#endif
        lo += segment * quarter + (segment != 0);
        count = segment == 3 ? count - 3 * quarter - 1 : quarter - (segment != 0);
    }
    while (count != 0) {
        const auto half = count / 2;
        const auto mid = lo + half;
        const bool before = Strict ? values[mid] < value : !(value < values[mid]);
        lo = before ? mid + 1 : lo;
        count = before ? count - half - 1 : half;
    }
    return lo;
}
template <bool Strict, class Index, bool Repeated = false, class T>
SIRKIT_LIS_NARROW_TARGET
std::vector<std::size_t> LISIndicesWithValuesNarrow(const std::vector<T>& v) {
    if (v.empty()) return {};
    std::vector<Index> tails;
#if SIRKIT_LIS_SEARCH_VARIANT == 2
    // gatherの要素型で所有し、異なる整数型へのポインタ変換を避ける。
    using Cached = std::conditional_t<std::is_same_v<T, std::int64_t>, decltype(_mm_cvtsi128_si64(_mm_setzero_si128())), decltype(_mm_cvtsi128_si32(_mm_setzero_si128()))>;
#else
    using Cached = T;
#endif
    std::vector<Cached> values;
    auto previous = std::make_unique_for_overwrite<Index[]>(v.size());
    tails.reserve(std::min(v.size(), std::size_t{64}));
#ifndef SKIP_RUNTIME_CHECKS
    reinsirk::detail::check_lis_value(v[0]);
#endif
    tails.push_back(0);
    values.reserve(std::min(v.size(), std::size_t{64}));
    values.push_back(v[0]);
    std::size_t i = 1, extensions = 0;
    for (; i < v.size(); ++i) {
#ifndef SKIP_RUNTIME_CHECKS
        reinsirk::detail::check_lis_value(v[i]);
#endif
        if (Strict ? values.back() < v[i] : !(v[i] < values.back())) {
            previous[i] = tails.back();
            if (values.size() == values.capacity()) {
                const auto capacity = values.capacity();
                values.reserve(capacity + std::min(capacity, v.size() - capacity));
            }
            if (values.size() == values.capacity()) std::unreachable();
            values.push_back(v[i]);
            tails.push_back(static_cast<Index>(i));
            if constexpr (std::is_same_v<T, std::int32_t>) {
